// 1. 加载 Landsat 8 TOA 影像并选择绿光波段 (B3)
var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122039_20151002');
var target_band = ls8.select('B3');

// 2. 均值滤波平滑处理（3x3 窗口）
var smooth_band = target_band.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels'})
});

// 3. 自定义 Prewitt 卷积核（X 与 Y 方向）
var prewittX = ee.Kernel.fixed(3, 3, [
  [-1, 0, 1],
  [-1, 0, 1],
  [-1, 0, 1]
], -1, -1, false);

var prewittY = ee.Kernel.fixed(3, 3, [
  [ 1,  1,  1],
  [ 0,  0,  0],
  [-1, -1, -1]
], -1, -1, false);

// 4. 卷积计算并求取边缘梯度模长
var gx = smooth_band.convolve(prewittX);
var gy = smooth_band.convolve(prewittY);
var enhanced_band = gx.hypot(gy); // sqrt(gx^2 + gy^2)

// 5. 中值滤波降噪
var final_band = enhanced_band.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});

// 6. 分别设置影像与边缘的可视化参数
