var chain_a_smooth = target_band.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels'})
});

// 自定义 Prewitt 卷积核（水平与垂直方向）
var prewittX = ee.Kernel.fixed(3, 3, [
  [-1, 0, 1],
  [-1, 0, 1],
  [-1, 0, 1]
], -1, -1, false);

var prewittY = ee.Kernel.fixed(3, 3, [
  [ 1,  1,  1],
  [ 0,  0,  0],
  [-1, -1, -1]
], -1, -1, false);

// 计算梯度模长
var gx = chain_a_smooth.convolve(prewittX);
var gy = chain_a_smooth.convolve(prewittY);
var chain_a_intermediate = gx.hypot(gy);

var chain_a_final = chain_a_intermediate.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});

// 3. 处理链 B：强平滑 + Laplacian 细节提取 + 中值滤波
var chain_b_smooth = target_band.reduceNeighborhood({
