var chain_b_intermediate = chain_b_smooth.convolve(kernel_b).abs();

var chain_b_final = chain_b_intermediate.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});

// 4. 适配 TOA 反射率的可视化参数
var original_vis = {
  min: 0.0,
  max: 0.3,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

