Map.addLayer(chain_a_intermediate, edge_vis_a, '链 A：Prewitt 边缘 (未滤波)', false);
Map.addLayer(chain_a_final, edge_vis_a, '链 A：Prewitt 边缘 (中值滤波)');
Map.addLayer(chain_b_intermediate, edge_vis_b, '链 B：Laplacian 边缘 (未滤波)', false);
Map.addLayer(chain_b_final, edge_vis_b, '链 B：Laplacian 边缘 (中值滤波)');

// 6. 设置地图中心
Map.setCenter(114.30, 30.61, 10);

// 1. 加载 Landsat 8 TOA 影像（武汉东北部）
var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122039_20151002');

// 选择绿色波段 (B3)
var target_band = ls8.select('B3');

// 2. 获取并打印原始投影信息
var crs = target_band.projection();
