    units: 'pixels'
  })
});

// 4. 可视化参数（灰度拉伸 0.0 ~ 0.3）
var vis_params = {
  min: 0.0,
  max: 0.3,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

// 5. 添加图层到地图
Map.addLayer(target_band, vis_params, '原始绿光波段 (B3)');
Map.addLayer(final_band, vis_params, '中值滤波平滑波段');

