// 2. 选择绿色波段 (B3)
var band_a = image_a.select('B3');
var band_b = image_b.select('B3');

// 3. 打印投影信息（二者均属同 UTM 投影带）
print('CRS of band_a:', band_a.projection());
print('CRS of band_b:', band_b.projection());

// 4. 合并两景影像（无缝拼接，无需强制 reproject 拖慢性能）
