// 5. 可视化参数
var vis_params = {
  min: 0.0,
  max: 0.3,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

// 6. 添加图层到地图
Map.addLayer(mosaic_band, vis_params, '拼接绿光波段 (B3)');
Map.addLayer(band_a, vis_params, '单景 A (Row 36)', false);
Map.addLayer(band_b, vis_params, '单景 B (Row 37)', false);

// 7. 定位至两景交界区域
Map.setCenter(114.74, 33.88, 8);

// 加载同轨相邻三景 Landsat 8 TOA 影像
var image_1 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_123035_20160504');
var image_2 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_123036_20160504');
var image_3 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_123037_20160504');

// 提取绿色波段并放入集合直接拼接
var coverage_collection = ee.ImageCollection([
  image_1.select('B3'),
  image_2.select('B3'),
  image_3.select('B3')
]);

var original_mosaic = coverage_collection.mosaic();

// 移除强制 reproject，直接以像素单位进行平滑，保证流畅缩放
var final_mosaic = original_mosaic.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});

var vis_params = {
  min: 0.0,
  max: 0.3,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

Map.addLayer(original_mosaic, vis_params, '原始拼接影像');
Map.addLayer(final_mosaic, vis_params, '中值平滑后拼接影像');
Map.setCenter(114.95, 34.60, 8);

// 1. 加载 Landsat 8 TOA 影像（修正 Asset ID）
var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122039_20151002');

// 选择波段
var red = ls8.select('B4');
var green = ls8.select('B3');
var blue = ls8.select('B2');
var original_display = ls8.select(['B4', 'B3', 'B2']);

// 2. 自定义 3x3 Prewitt 核
var prewittX = ee.Kernel.fixed(3, 3, [[-1, 0, 1], [-1, 0, 1], [-1, 0, 1]], -1, -1, false);
var prewittY = ee.Kernel.fixed(3, 3, [[1, 1, 1], [0, 0, 0], [-1, -1, -1]], -1, -1, false);

// 3. 绿波段平滑并提取边缘
var smooth_green = green.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels'})
});
var gx = smooth_green.convolve(prewittX);
var gy = smooth_green.convolve(prewittY);
var green_edge = gx.hypot(gy);

// 4. 将边缘以一定权重叠加回原波段（锐化增强），而不是直接替换
var enhanced_green = green.add(green_edge.multiply(1.5));
var optimized_display = ee.Image.cat([red, enhanced_green, blue]);

// 5. 可视化参数（适配 TOA 反射率 0.0 ~ 0.3）
var vis_params = {
  min: 0.0,
  max: 0.3
};

Map.addLayer(original_display, vis_params, '原始自然色 (RGB)');
Map.addLayer(optimized_display, vis_params, '绿波段边缘增强后自然色');
Map.setCenter(114.30, 30.61, 10);

// 1. 加载 Landsat 8 全色波段 (B8，15m 分辨率)
var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122039_20151002');
var original_display = ls8.select('B8');

// 2. 平滑滤波（均值 + 中值）
var smooth_1 = original_display.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels'})
});
var smooth_2 = smooth_1.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});

// 3. Prewitt 算子提取边缘
var prewittX = ee.Kernel.fixed(3, 3, [[-1, 0, 1], [-1, 0, 1], [-1, 0, 1]], -1, -1, false);
var prewittY = ee.Kernel.fixed(3, 3, [[1, 1, 1], [0, 0, 0], [-1, -1, -1]], -1, -1, false);
var gx = smooth_2.convolve(prewittX);
var gy = smooth_2.convolve(prewittY);
var stage_display = gx.hypot(gy);

// 4. 边缘中值滤波去噪
var final_display = stage_display.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});

// 5. 可视化参数
var raw_vis = { min: 0.0, max: 0.3, palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff'] };
var edge_vis = { min: 0.0, max: 0.08, palette: ['#000000', '#555555', '#aaaaaa', '#ffffff'] };

Map.addLayer(original_display, raw_vis, '原始全色波段 (B8)');
Map.addLayer(stage_display, edge_vis, 'Prewitt 边缘 (stage)', false);
Map.addLayer(final_display, edge_vis, '滤波后 Prewitt 边缘 (final)');
Map.setCenter(114.30, 30.61, 10);

var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122039_20151002');
var original_display = ls8.select('B8');

// --- 方案 A：均值滤波 -> Prewitt 梯度模长 -> 中值去噪 ---
var chain_a_smooth = original_display.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels'})
});
var prewittX = ee.Kernel.fixed(3, 3, [[-1, 0, 1], [-1, 0, 1], [-1, 0, 1]], -1, -1, false);
var prewittY = ee.Kernel.fixed(3, 3, [[1, 1, 1], [0, 0, 0], [-1, -1, -1]], -1, -1, false);
var gx = chain_a_smooth.convolve(prewittX);
var gy = chain_a_smooth.convolve(prewittY);
var chain_a_stage = gx.hypot(gy);
var chain_a_final = chain_a_stage.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});

// --- 方案 B：中值滤波 -> Laplacian 二阶边缘 -> 均值滤波 ---
var chain_b_smooth = original_display.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels'})
});
var chain_b_stage = chain_b_smooth.convolve(ee.Kernel.laplacian4()).abs();
var chain_b_final = chain_b_stage.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels'})
});

// --- 分别配置显示参数 ---
var raw_vis = { min: 0.0, max: 0.3, palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff'] };
var edge_vis_a = { min: 0.0, max: 0.08, palette: ['#000000', '#ffffff'] };
