// 地理探测器 q 统计量计算函数
function geoDetector(y, x, geometry) {
  var stats = y.reduceRegion({
    reducer: ee.Reducer.variance().combine(ee.Reducer.count(), '', true),
    geometry: geometry,
    scale: 90,
    maxPixels: 1e8
  });
  var totalVar = ee.Number(stats.get('nd_variance'));
  var totalCount = ee.Number(stats.get('nd_count'));

  var grouped = y.addBands(x.rename('strata')).reduceRegion({
    reducer: ee.Reducer.variance().combine(ee.Reducer.count(), '', true).group({
      groupField: 1,
      groupName: 'strata'
    }),
    geometry: geometry,
    scale: 90,
    maxPixels: 1e8
  });

  var groupList = ee.List(grouped.get('groups'));
  var withinSum = groupList.map(function(item) {
    var dict = ee.Dictionary(item);
    var v = ee.Number(dict.get('variance'));
    var c = ee.Number(dict.get('count'));
    return v.multiply(c);
  }).reduce(ee.Reducer.sum());

  var q = ee.Number(1).subtract(ee.Number(withinSum).divide(totalVar.multiply(totalCount)));
  return q;
}

