// 空间加权邻域统计与局部自相关近似
var feature = ee.FeatureCollection('projects/your-project/assets/EasternChina_PopulationAging_Vector');

Map.setCenter(115, 31, 4);

var globalMean = ee.Number(feature.aggregate_mean('aging'));

// 使用空间 Join 与缓冲计算局部加权均值
var spatialFilter = ee.Filter.withinDistance({
  distance: 50000,
  leftField: '.geo',
  rightField: '.geo',
  maxError: 1000
});

var joined = ee.Join.saveAll({matchesKey: 'neighbors'}).apply(feature, feature, spatialFilter);

var lisaResult = joined.map(function(f) {
  var geom = f.geometry();
  var aging = ee.Number(f.get('aging'));
  var neighbors = ee.FeatureCollection(ee.List(f.get('neighbors')));

  var weights = neighbors.map(function(n) {
    var dist = geom.distance(n.geometry());
    var weight = ee.Number(1).divide(dist.add(1));
    return n.set('weight', weight);
  });

  var sumWeight = ee.Number(weights.aggregate_sum('weight'));
  var sumWeightedAging = ee.Number(weights.reduceColumns({
    reducer: ee.Reducer.sum(),
    selectors: ['aging']
  }).get('sum'));

  var localMoran = aging.subtract(globalMean)
    .multiply(sumWeightedAging.divide(sumWeight).subtract(globalMean));

  return f.set('LISA', localMoran);
});

Map.addLayer(lisaResult, {color: '#FFFF00'}, 'LISA结果');

