var swir1 = lc08.select('B6');
var swir2 = lc08.select('B7');

// AWEIsh = Blue + 2.5 * Green - 1.5 * (NIR + SWIR1) - 0.25 * SWIR2
var aweish = blue.add(green.multiply(2.5))
