var swir2 = lc08.select('B7');

// WI2015 = 1.7204 + 171*Green + 3*Red - 70*NIR - 45*SWIR1 - 71*SWIR2
var wi2015 = green.multiply(171.0)
  .add(red.multiply(3.0))
  .subtract(nir.multiply(70.0))
  .subtract(swir1.multiply(45.0))
  .subtract(swir2.multiply(71.0))
  .add(1.7204);

