// Landsat 8 增强型植被指数 (EVI) 与叶面积指数 (LAI) 估算
var point = ee.Geometry.Point([114.28, 30.57]);

var lc08 = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
  .filterBounds(point)
