  .first();

var blue = lc08.select('B2');
var red = lc08.select('B4');
var nir = lc08.select('B5');

// EVI 计算: 2.5 * ((NIR - Red) / (NIR + 6*Red - 7.5*Blue + 1))
var evi = nir.subtract(red).multiply(2.5).divide(
  nir.add(red.multiply(6.0)).subtract(blue.multiply(7.5)).add(1.0)
);

// LAI 估算: 3.618 * EVI - 0.118
var lai = evi.multiply(3.618).subtract(0.118).max(0);

