var dem = ee.Image('USGS/SRTMGL1_003').select('elevation');

var ndvi_clip = ndvi.updateMask(dem.mask());
var dem_clip = dem.updateMask(ndvi_clip.mask());

// 计算地形因子
var gradient = dem_clip.gradient();
var dx = gradient.select('x');
var dy = gradient.select('y');
var slope = dx.hypot(dy).atan().multiply(180 / Math.PI);
var aspect = dx.atan2(dy.multiply(-1)).multiply(180 / Math.PI).add(180);

// 重分类
var dem_class = ee.Image(1)
  .where(dem_clip.gte(1500).and(dem_clip.lt(2500)), 2)
  .where(dem_clip.gte(2500).and(dem_clip.lt(3000)), 3)
  .where(dem_clip.gte(3000).and(dem_clip.lt(3500)), 4)
  .where(dem_clip.gte(3500), 5);

var slope_class = ee.Image(1)
  .where(slope.gte(5).and(slope.lt(15)), 2)
  .where(slope.gte(15).and(slope.lt(25)), 3)
  .where(slope.gte(25).and(slope.lt(35)), 4)
  .where(slope.gte(35), 5);

var aspect_class = ee.Image(1)
  .where(aspect.gte(60).and(aspect.lt(120)), 2)
  .where(aspect.gte(120).and(aspect.lt(180)), 3)
  .where(aspect.gte(180).and(aspect.lt(240)), 4)
  .where(aspect.gte(240).and(aspect.lt(300)), 5)
  .where(aspect.gte(300), 6);

// 地理探测器函数
function geoDetector(y, strata, geometry) {
  var stats = y.reduceRegion({
    reducer: ee.Reducer.variance().combine(ee.Reducer.count(), '', true),
    geometry: geometry,
    scale: 90,
    maxPixels: 1e8
  });
  var totalVar = ee.Number(stats.get('nd_variance'));
  var totalCount = ee.Number(stats.get('nd_count'));

  var grouped = y.addBands(strata.rename('strata')).reduceRegion({
    reducer: ee.Reducer.variance().combine(ee.Reducer.count(), '', true).group({
      groupField: 1,
      groupName: 'strata'
    }),
    geometry: geometry,
    scale: 90,
    maxPixels: 1e8
  });

  var groupList = ee.List(grouped.get('groups'));
  var withinSum = groupList.map(function(item) {
    var dict = ee.Dictionary(item);
    return ee.Number(dict.get('variance')).multiply(ee.Number(dict.get('count')));
  }).reduce(ee.Reducer.sum());

  return ee.Number(1).subtract(ee.Number(withinSum).divide(totalVar.multiply(totalCount)));
}

var sampleGeom = landsat8.geometry();
print('高程因子解释结果 (q值):', geoDetector(ndvi_clip, dem_class, sampleGeom));
print('坡度因子解释结果 (q值):', geoDetector(ndvi_clip, slope_class, sampleGeom));
print('坡向因子解释结果 (q值):', geoDetector(ndvi_clip, aspect_class, sampleGeom));

