// Landsat 8 改进型垂直干旱指数 (MPDI)
var point = ee.Geometry.Point([114.28, 30.57]);

var lc08 = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
  .filterBounds(point)
  .filterDate('2015-09-15', '2015-10-15')
  .sort('CLOUD_COVER')
  .first();

var nir = lc08.select('B5');
var red = lc08.select('B4');

// 计算 NDVI
var ndvi = lc08.normalizedDifference(['B5', 'B4']);

var M = 2.0;
var NDVI_soil = 0.1;
var NDVI_veg = 0.9;

// 植被覆盖度 f_v
var f_v = ndvi.subtract(NDVI_soil).divide(NDVI_veg - NDVI_soil).clamp(0, 1);

var R_red_v = 0.25;

var term1 = red.add(red.multiply(M));
var term2 = f_v.multiply(nir.multiply(M).add(R_red_v));
var term3 = ee.Image(1).subtract(f_v).multiply(Math.sqrt(1 + M * M));

var mpdi = term1.subtract(term2).divide(term3);

var vis_params = {
  min: 0,
  max: 1,
  palette: [
    '#0000FF', '#00FFFF', '#00FF00', '#FFFF00',
    '#FFA500', '#FF0000', '#800000'
  ]
};

Map.setCenter(114.28, 30.57, 7);
Map.addLayer(mpdi, vis_params, '垂直干旱指数 MPDI');

