// 基于空间缓冲区与路径成本的路径规划模拟
var startCoords = ee.Geometry.Point([114.337475, 30.558570]);
var endCoords = ee.Geometry.Point([114.328842, 30.542172]);

// 创建起点和终点要素与缓冲区
var start = ee.Feature(startCoords, {name: 'start'});
var end = ee.Feature(endCoords, {name: 'end'});
var startBuffer = start.buffer(100);
var endBuffer = end.buffer(100);

// 构建分析区域与模拟道路段
var corridor = ee.Geometry.LineString([
  [114.337475, 30.558570],
  [114.333000, 30.550000],
  [114.328842, 30.542172]
]);

var roadFeature = ee.Feature(corridor, {name: 'main_path'});
var roadCollection = ee.FeatureCollection([roadFeature]);

// 计算道路几何长度（米）
var roadsWithLength = roadCollection.map(function(f) {
  var length = f.geometry().length();
  return f.set('length', length);
});

// 计算通行耗时（分钟）
var fastestPath = roadsWithLength.map(function(f) {
  var speed = 50 * 1000 / 60; // 50 km/h 转换为 m/min
  var time = ee.Number(f.get('length')).divide(speed);
  return f.set('time', time);
});

var speedLimitPath = roadsWithLength.map(function(f) {
  var speed = 30 * 1000 / 60; // 30 km/h 限速
  var time = ee.Number(f.get('length')).divide(speed);
  return f.set('time', time);
});

Map.setCenter(114.33, 30.55, 14);
Map.addLayer(startBuffer, {color: '000000'}, '起点');
Map.addLayer(endBuffer, {color: '000000'}, '终点');
Map.addLayer(roadsWithLength.style({color: 'FFCC33', width: 3}), {}, '最短路径');
Map.addLayer(fastestPath.style({color: 'FF99CC', width: 2}), {}, '最快路径 (50km/h)');
Map.addLayer(speedLimitPath.style({color: '33CC66', width: 2}), {}, '限速路径 (30km/h)');

