// Landsat 8 温度植被干旱指数 (TVDI) 计算
var point = ee.Geometry.Point([114.28, 30.57]);

var lc08 = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
  .filterBounds(point)
  .filterDate('2015-09-15', '2015-10-15')
  .sort('CLOUD_COVER')
  .first();

// 计算 NDVI
var ndvi = lc08.normalizedDifference(['B5', 'B4']);

// 计算地表温度 (°C)
var b10 = lc08.select('B10');
var lst_c = b10.subtract(273.15);

// 定义干湿边参数
var a_wet = 25.0;
var b_wet = -10.0;
var a_dry = 45.0;
var b_dry = -5.0;

// 计算湿边和干边温度
var lst_min = ndvi.multiply(b_wet).add(a_wet);
var lst_max = ndvi.multiply(b_dry).add(a_dry);

// 计算 TVDI = (LST - LST_min) / (LST_max - LST_min)
var tvdi = lst_c.subtract(lst_min).divide(lst_max.subtract(lst_min));

var vis_params = {
  min: 0,
  max: 1,
  palette: ['#0000FF', '#00FFFF', '#00FF00', '#FFFF00', '#FFA500', '#FF0000', '#800000']
};

Map.setCenter(114.28, 30.57, 7);
Map.addLayer(tvdi, vis_params, '温度植被干旱指数 TVDI');

